package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.compounding.*;
import dev.cosmerearcanists.equipment.*;
import dev.cosmerearcanists.hemalurgy.*;
import dev.cosmerearcanists.nicrosil.NicrosilPowers;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.inventory.ClickType;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class ImplantGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"ImplantTest"));p.setGameMode(GameType.SURVIVAL);PowerAttributes.migrate(p);return p;}
    private static void visited(FakePlayer p){var dimensions=HemalurgyConfig.SCADRIAL_DIMENSIONS.get();try{HemalurgyConfig.SCADRIAL_DIMENSIONS.set(List.of(p.level().dimension().location().toString()));ScadrialVisits.observe(p);}finally{HemalurgyConfig.SCADRIAL_DIMENSIONS.set(dimensions);}}
    private static HemalurgyMenu menu(FakePlayer p){var menu=new HemalurgyMenu(7,p.getInventory());p.containerMenu=menu;return menu;}
    private static ItemStack power(String metal,String key,UUID donor){var s=new ItemStack(EquipmentContent.SPIKES.get(metal).get());HemalurgicSpikes.store(s,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,metal,key,List.of(new IdentityMath.Portion(donor,.8))));return s;}
    private static ItemStack connection(UUID donor,String world){var s=new ItemStack(EquipmentContent.SPIKES.get("duralumin").get());HemalurgicSpikes.store(s,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,"duralumin",DuraluminTheft.POWER,List.of(new IdentityMath.Portion(donor,1)),HemalurgicTraits.NONE,HemalurgicTraits.NO_COGNITION,new StolenConnection(donor,world,Map.of())));return s;}
    private static boolean place(FakePlayer p,ItemStack item,int point){p.containerMenu.setCarried(item);var ideal=ImplantRules.POINTS.get(point);return ImplantService.place(p,ideal.back(),ideal.u(),ideal.v());}
    @GameTest(template="empty") public static void visitHistoryIsPersistentAndOriginAloneDoesNotUnlock(GameTestHelper h){var p=player(h);new OriginData("scadrial","human","none","none").save(p);h.assertTrue(!ImplantService.screenAllowed(p),"Origin selection alone does not fabricate an actual visit");visited(p);h.assertTrue(ImplantService.screenAllowed(p),"Actual observed dimension visit unlocks screen");var replacement=player(h);PowerData.clonePlayer(p,replacement);h.assertTrue(ScadrialVisits.visited(replacement)&&ImplantService.screenAllowed(replacement),"Visit survives respawn copying");h.succeed();}
    @GameTest(template="empty") public static void stolenConnectionBootstrapsThroughNativeCursorWithoutPermanentVisit(GameTestHelper h){var p=player(h);var donor=UUID.randomUUID();var spike=connection(donor,"scadrial");p.getInventory().setItem(9,spike);h.assertTrue(ImplantService.screenAllowed(p)&&!ImplantService.connected(p),"Held Connection authorizes limited bootstrap, not full powers");var menu=menu(p);menu.clicked(13,0,ClickType.PICKUP,p);h.assertTrue(p.getInventory().getItem(9).isEmpty()&&menu.getCarried().getCount()==1,"Native inventory cursor owns the single physical spike");var heart=ImplantRules.POINTS.get(11);h.assertTrue(ImplantService.place(p,false,heart.u(),heart.v())&&menu.getCarried().isEmpty()&&ImplantService.implants(p).size()==1,"Placement moves cursor item into body exactly once");h.assertTrue(ImplantService.connected(p)&&IdentityAccess.accepts(p,donor)&&!ScadrialVisits.visited(p),"Active stolen Scadrial Connection unlocks without falsifying history");menu.refresh();menu.clicked(11,0,ClickType.CLONE,p);h.assertTrue(menu.getCarried().isEmpty(),"Native container clicks cannot clone protected body display slots");h.assertTrue(ImplantService.remove(p,11)&&HemalurgicSpikes.contents(menu.getCarried()).id().equals(HemalurgicSpikes.contents(spike).id()),"Removal returns same charge to native cursor");h.assertTrue(!ImplantService.connected(p)&&!IdentityAccess.accepts(p,donor),"Borrowed access ends immediately on removal");h.succeed();}
    @GameTest(template="empty") public static void bootstrapCannotInstallUnrelatedPowersAndStalePacketsDoNotMutate(GameTestHelper h){var p=player(h);p.getInventory().setItem(9,connection(UUID.randomUUID(),"scadrial"));var menu=menu(p);var spike=power("steel","a:steel",UUID.randomUUID());menu.setCarried(spike);var eye=ImplantRules.POINTS.get(0);h.assertTrue(!ImplantService.place(p,false,eye.u(),eye.v()),"Must activate Connection before other implants");visited(p);HemalurgyNetwork.request(p,new HemalurgyNetwork.Request(1,menu.containerId,menu.getStateId()+1,false,eye.u(),eye.v(),-1));h.assertTrue(ImplantService.implants(p).isEmpty()&&menu.getCarried()==spike,"Stale native menu revision preserves item/body");HemalurgyNetwork.request(p,new HemalurgyNetwork.Request(1,999,menu.getStateId(),false,eye.u(),eye.v(),-1));h.assertTrue(ImplantService.implants(p).isEmpty(),"Wrong container cannot mutate body");h.succeed();}
    @GameTest(template="empty") public static void implantedPowersAreExternalIdentityPreservingAndStopOnRemoval(GameTestHelper h){var p=player(h);visited(p);var menu=menu(p);var donor=UUID.randomUUID();h.assertTrue(place(p,power("steel","a:steel",donor),0),"Compatible eye accepts steel");h.assertTrue(Math.abs(PowerAttributes.strength(p,"a:steel")-.8)<1e-8&&PowerAttributes.baseStrength(p,"a:steel")==0&&NicrosilPowers.personal(p,"a:steel")==0,"External attribute grants power but cannot launder into personal nicrosil storage");h.assertTrue(PowerSources.components(p,"a:steel").stream().anyMatch(v->donor.equals(v.identity())),"Original source Identity preserved");PowerData.state(p,"a:steel",2);h.assertTrue(ImplantService.remove(p,0)&&PowerAttributes.strength(p,"a:steel")==0&&PowerData.state(p,"a:steel")==0,"Removal ends stolen ability immediately");h.succeed();}
    @GameTest(template="empty") public static void linchpinRetainsPowerAndRemovalUsesPreRemovalCount(GameTestHelper h){var p=player(h);visited(p);menu(p);UUID donor=UUID.randomUUID();h.assertTrue(place(p,power("steel","a:steel",donor),0)&&place(p,power("steel","a:iron",donor),1)&&place(p,power("bronze","a:bronze",donor),2)&&place(p,power("bronze","a:bronze",donor),3)&&place(p,power("steel","a:pewter",donor),4),"Five compatible points install");h.assertTrue(Math.abs(SpiritualIntegrity.get(p)+.875)<1e-8,"Five spikes without linchpin use50%worse costs and negative integrity");h.assertTrue(place(p,power("steel","a:tin",donor),12)&&ImplantService.linchpin(p)&&PowerAttributes.strength(p,"a:tin")>.79,"Linchpin supplies stored power and stabilization");h.assertTrue(Math.abs(SpiritualIntegrity.get(p)+.5)<1e-8,"All six points still pay normal25%cost");p.setHealth(20);h.assertTrue(ImplantService.remove(p,12)&&Math.abs(p.getHealth()-10)<1e-6,"Linchpin removal from6spikes deals5hearts");h.assertTrue(!ImplantService.linchpin(p)&&PowerAttributes.strength(p,"a:tin")==0&&Math.abs(SpiritualIntegrity.get(p)+1.125)<1e-8,"Removal activates missing-linchpin penalty and one residual wound");h.succeed();}
    @GameTest(template="empty") public static void incompatiblePlacementAndRepeatedRemovalUseOneWoundPerPoint(GameTestHelper h){var p=player(h);visited(p);menu(p);var spike=power("steel","a:steel",UUID.randomUUID());h.assertTrue(place(p,spike,8)&&ImplantService.misplaced(p),"Wrong point accepts physical item but inflicts a timed debuff");h.assertTrue(PowerAttributes.strength(p,"a:steel")==0&&p.getMaxHealth()==15&&Math.abs(p.getAttributeValue(Attributes.ATTACK_DAMAGE)-.75)<1e-8&&Math.abs(p.getAttributeValue(PowerAttributes.IMPLANT_VISION)-.85)<1e-8,"Wrong placement grants no power and applies health/damage/vision reductions");h.assertTrue(ImplantService.remove(p,8),"Remove wrong spike");var carried=p.containerMenu.getCarried();h.assertTrue(place(p,carried,8)&&Math.abs(SpiritualIntegrity.get(p)-.75)<1e-8,"Reinsertion replaces residual contribution instead of stacking");h.assertTrue(ImplantService.remove(p,8)&&PowerData.data(p).getCompound("hemalurgic_wounds").getAllKeys().size()==1&&Math.abs(SpiritualIntegrity.get(p)-.75)<1e-8,"Repeated removal leaves one wound per bind point");var wound=PowerData.data(p).getCompound("hemalurgic_wounds").getCompound("8");h.assertTrue(wound.getLong("until")==p.server.overworld().getGameTime()+168000&&wound.getLong("misplaced_until")==p.server.overworld().getGameTime()+24000,"Independent week/day timers");wound.putLong("until",p.server.overworld().getGameTime());wound.putLong("misplaced_until",p.server.overworld().getGameTime());ImplantService.apply(p);h.assertTrue(SpiritualIntegrity.get(p)==1&&p.getMaxHealth()==20,"Exact expiry removes both penalties");h.succeed();}
    @GameTest(template="empty") public static void activeIdentityEnablesCompoundingAndAluminumSuspendsIt(GameTestHelper h){var p=player(h);visited(p);menu(p);var donor=UUID.randomUUID();PowerAttributes.set(p,"a:steel",1);h.assertTrue(place(p,power("pewter","f:steel",donor),11)&&!CompoundingService.eligible(p,"steel"),"Different keyed sources cannot compound initially");h.assertTrue(place(p,connection(donor,"scadrial"),12)&&CompoundingService.eligible(p,"steel"),"Active donor Identity joins native and donor source powers");AluminumSuppression.apply(p);ImplantService.apply(p);h.assertTrue(PowerAttributes.strength(p,"f:steel")==0&&IdentityAccess.implanted(p).isEmpty()&&!CompoundingService.eligible(p,"steel"),"Aluminum blocks powers and borrowed Identity");h.assertTrue(ImplantService.implants(p).size()==2,"Suppression preserves physical implants");h.succeed();}
    @GameTest(template="empty") public static void implantsAndPerPointWoundsSurviveCloneAndNegativeDamageIsNotDoubled(GameTestHelper h){var p=player(h);visited(p);menu(p);h.assertTrue(place(p,power("steel","a:steel",UUID.randomUUID()),0),"Install");SpiritualIntegrity.damage(p,.2);h.assertTrue(Math.abs(SpiritualIntegrity.get(p)-.55)<1e-8,"Permanent damage subtracts once, separately from implant costs");var copy=player(h);PowerData.clonePlayer(p,copy);ImplantService.apply(copy);h.assertTrue(ImplantService.implants(copy).size()==1&&PowerAttributes.strength(copy,"a:steel")>.79&&Math.abs(SpiritualIntegrity.get(copy)-.55)<1e-8,"Clone preserves physical charge and restores external grants without base laundering");h.succeed();}
    @GameTest(template="empty") public static void thirteenPointLimitAndChargeIdsPreventExtraImplants(GameTestHelper h){var p=player(h);visited(p);menu(p);for(int point=0;point<13;point++)h.assertTrue(place(p,power("steel","a:steel",UUID.randomUUID()),point),"Every anatomical point can hold one physical spike");var extra=power("steel","a:iron",UUID.randomUUID());h.assertTrue(!place(p,extra,0)&&ImplantService.implants(p).size()==13&&p.containerMenu.getCarried()==extra,"Fourteenth/occupied-point attempt keeps carried item");h.assertTrue(Math.abs(SpiritualIntegrity.get(p)+2.25)<1e-8,"Thirteen implants with linchpin cost325%integrity");var q=player(h);visited(q);menu(q);var spike=power("steel","a:steel",UUID.randomUUID());h.assertTrue(place(q,spike,0)&&!place(q,spike.copy(),1),"Same charge UUID cannot duplicate into a second point");h.succeed();}
    @GameTest(template="empty") public static void naturalTraitsGrantSensesStrengthResistanceAndMemory(GameTestHelper h){var p=player(h);visited(p);menu(p);var donor=UUID.randomUUID();var iron=new ItemStack(EquipmentContent.SPIKES.get("iron").get());HemalurgicSpikes.store(iron,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,"iron",HemalurgicTraits.STRENGTH,List.of(new IdentityMath.Portion(donor,3))));var tin=new ItemStack(EquipmentContent.SPIKES.get("tin").get());HemalurgicSpikes.store(tin,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,"tin",HemalurgicTraits.SENSES,List.of(new IdentityMath.Portion(donor,.12)),new HemalurgicTraits.Senses(.03,.12,.03)));h.assertTrue(place(p,iron,4)&&place(p,tin,5)&&Math.abs(p.getAttributeValue(Attributes.ATTACK_DAMAGE)-4)<1e-8&&Math.abs(p.getAttributeValue(PowerAttributes.HEARING)-1.12)<1e-8,"Natural physical bonuses use existing sensory attributes without Feruchemy base grants");var q=player(h);visited(q);menu(q);var zinc=new ItemStack(EquipmentContent.SPIKES.get("zinc").get());HemalurgicSpikes.store(zinc,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,"zinc",HemalurgicTraits.FORTITUDE,List.of(new IdentityMath.Portion(donor,.4)),HemalurgicTraits.NONE,new HemalurgicTraits.Cognition(.4,0)));var copper=new ItemStack(EquipmentContent.SPIKES.get("copper").get());HemalurgicSpikes.store(copper,new HemalurgicSpikes.Charge(UUID.randomUUID(),donor,"copper",HemalurgicTraits.MEMORY,List.of(new IdentityMath.Portion(donor,.25)),HemalurgicTraits.NONE,new HemalurgicTraits.Cognition(.25,.75)));h.assertTrue(place(q,zinc,4)&&place(q,copper,5)&&Math.abs(ImplantService.resistance(q)-.55)<1e-8&&ImplantService.memoryBonus(q)==.75,"Bounded mental resistance composes and memory bonus caps75%");var mind=new ItemStack(Items.COPPER_INGOT);dev.cosmerearcanists.feruchemy.Metalminds.transfer(mind,q.getUUID(),"copper",10);h.assertTrue(dev.cosmerearcanists.copper.CopperService.capacityBytes(q,mind)>dev.cosmerearcanists.copper.CopperService.capacityBytes(mind),"Memory bonus increases charge-backed copper byte capacity");h.succeed();}
    @GameTest(template="empty") public static void negativeIntegrityLowersEmotionalTakeoverThreshold(GameTestHelper h){var source=player(h);var target=player(h);SpiritualIntegrity.set(target,.5);DominationService.attempt(source,target,"a:zinc",3,10);h.assertTrue(DominationService.owner(target)==null,"Subthreshold compliance does not dominate at nonnegative integrity");SpiritualIntegrity.set(target,-.5);DominationService.attempt(source,target,"a:zinc",3,10);h.assertTrue(DominationService.owner(target)==source,"Negative integrity amplifies takeover vulnerability");DominationService.remove(target);h.succeed();}
}
